contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        string memory firstReturnedVersion;
        bool firstReverted;
        try c.version() returns (string memory v) {
            firstReturnedVersion = v;
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        string memory secondReturnedVersion;
        bool secondReverted;
        try c.version() returns (string memory v) {
            secondReturnedVersion = v;
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(firstReverted || secondReverted || keccak256(bytes(firstReturnedVersion)) == keccak256(bytes(secondReturnedVersion)));
    }
}

